import {SAVE_KEY,CATALOG,ROOMS,GUESTS,COSMETICS,ACHIEVEMENTS,freshState,loadState,dimensions,blocked,pathfind,approach,canPlace,moveContinuous,checkUnlocks,progress,isUnlocked,spin,SKIN_TONES,HAIR_STYLES,PRESENTATIONS,STORE_ITEMS,purchaseCosmetic,RTP,HIT_RATE,REFILL_BELOW,REFILL_AMOUNT,canRefill,refill,paytableLines} from './engine.js';
import {HotelResidents} from './residents.js';
import {residentReply} from './characters.js';
import {icon,esc,project,unproject,roomArt,objectArt,objectSvg,avatarArt,avatarSvg,symbolSvg} from './art.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let storageOK=true;let state;try{state=loadState(localStorage.getItem(SAVE_KEY));}catch{state=freshState();storageOK=false;}
const hotel=new HotelResidents();
let chatTarget=null,storeFilter='all',roomChatLogs={suite:[],lobby:[],gold:[],neon:[],roof:[]};
let currentRoom='suite',player={x:4.5,y:4.5},path=[],onArrival=null,objects=[],npcs=[],roomNodes=[],hero,depthLayer,targetLayer,ghostLayer;
let editing=false,selection=null,ghost=null,ghostValid=false,panelType='',activeGame='gold',spinning=false,zoom=1,fit=false;
let camera={x:500,y:375},keys=new Set(),stick={x:0,y:0,active:false,id:null},lastTime=0,elapsed=0,notified=new Set(),toastTimer,noticeTimer,frame=0,audio,chatMessages=[],spinTimer;
const world=$('#world'),game=$('.game'),panel=$('#panel');
const navLabels={suite:'My Suite',hotel:'Explore Hotel',avatar:'Avatar',rewards:'Achievements'};
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch{if(storageOK)toast('This browser could not save progress. Keep this tab open.');storageOK=false;}updateHud();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function notice(message){$('#scene-notice').textContent=message;$('#scene-notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#scene-notice').hidden=true,3000);}
function updateProgress(){const unlocked=checkUnlocks(state);for(const a of unlocked){if(!notified.has(a.id)){notified.add(a.id);toast(`Unlocked: ${a.reward} · ${a.name}`);tone(660,.12);}}save();updateSidebar();}
function updateHud(){ $('#credits').textContent=state.credits.toLocaleString();$('#player-name').innerHTML=`${esc(state.name)}<small>SUITE 408 · DEMO</small>`;$('#side-name').textContent=state.name;$('#hud-avatar').innerHTML=avatarSvg(state);$('#side-avatar').innerHTML=avatarSvg(state);$('.sound-button').innerHTML=icon(state.sound?'sound':'mute',17);$('.settings-button').innerHTML=icon('settings',21);}
function updateSidebar(){
 const incomplete=ACHIEVEMENTS.filter(a=>!a.demo&&!state.unlocked.includes(a.id)),rows=incomplete.length?incomplete.slice(0,2):ACHIEVEMENTS.slice(0,2);
 $('#achievement-count').textContent=`${state.unlocked.length} / 6`;
 $('#mini-achievements').innerHTML=rows.map(a=>`<div class="mini-achievement"><div class="mini-achievement-icon">${icon(state.unlocked.includes(a.id)?'check':'star',17)}</div><div><strong>${esc(a.name)}</strong><p>${esc(a.desc)}</p></div><em>${Math.min(progress(a,state),a.target)}/${a.target}</em></div>`).join('');
 const around=npcs.length?npcs.slice(0,3):hotel.inRoom('lobby').slice(0,3);
 $('#guest-list').innerHTML=around.map(g=>`<button class="guest-row" data-action="guest" data-index="${g.id}"><div class="guest-portrait">${guestSvg(g)}</div><div><strong>${g.name}</strong><span>${esc(g.title)}</span><span>${ROOMS[g.room].short} · ${esc(hotel.describe(g))}</span></div><i></i></button>`).join('')+`<button class="text-button" style="margin-top:18px" data-action="people">Meet all 20 residents →</button>`;
}
function guestSvg(g){return `<svg viewBox="-34 -104 68 115" aria-hidden="true">${avatarArt(g,true)}</svg>`;}
function navActive(key){$$('.rail [data-action],.bottom-nav [data-action]').forEach(b=>b.classList.toggle('active',b.dataset.action===key));}
function setupNav(){$$('.rail .nav-item,.bottom-nav button').forEach(b=>{b.innerHTML=icon(b.dataset.action==='hotel'?'hotel':b.dataset.action,22)+`<span>${navLabels[b.dataset.action]}</span>`;});$('.sound-button').innerHTML=icon('mute',17);$('.chat-fab').insertAdjacentHTML('beforeend',icon('chat',23));$('.store-fab').innerHTML=icon('store',22)+'<span>Store</span>';$('.people-fab').innerHTML=icon('people',22)+'<span>Residents</span>';$$('.camera-tools button').forEach(b=>b.innerHTML=icon(b.dataset.action==='zoom-in'?'plus':b.dataset.action==='zoom-out'?'minus':'fit',17));}
function freeSpawn(room){let [x,y]=room.spawn;if(!blocked(x,y,objects))return{x:x+.5,y:y+.5};for(let a=2;a<8;a++)for(let b=2;b<8;b++)if(!blocked(a,b,objects))return{x:a+.5,y:b+.5};return{x:7.5,y:7.5};}
function enterRoom(id){
 if(!ROOMS[id])return;editing=false;ghost=null;selection=null;chatTarget=null;game.classList.remove('edit-mode');$('#editbar').hidden=true;currentRoom=id;objects=id==='suite'?state.furniture:structuredClone(ROOMS[id].objects);player=freeSpawn(ROOMS[id]);path=[];onArrival=null;stopStick();keys.clear();npcs=hotel.inRoom(id);
 if(!state.visited.includes(id))state.visited.push(id);$('#room-floor').textContent=ROOMS[id].floor;$('#room-name').textContent=ROOMS[id].name;$('#room-tag').textContent=ROOMS[id].tag;
 $('.edit-button').innerHTML=id==='suite'?icon('edit',16)+'<span>Decorate</span>':icon('hotel',16)+'<span>Directory</span>';$('.edit-button').setAttribute('aria-label',id==='suite'?'Decorate your suite':'Open hotel directory');navActive(id==='suite'?'suite':'hotel');world.classList.remove('room-enter');void world.clientWidth;world.classList.add('room-enter');drawScene();camera={x:500,y:390};updateProgress();updateChatDefaults();closePanel();
}
function svgNode(markup){const tmp=document.createElementNS('http://www.w3.org/2000/svg','g');tmp.innerHTML=markup;return tmp;}
function drawScene(){
 world.innerHTML=roomArt(ROOMS[currentRoom],state)+'<g id="target-layer"></g><g id="depth-layer"></g><g id="ghost-layer"></g>';depthLayer=$('#depth-layer');targetLayer=$('#target-layer');ghostLayer=$('#ghost-layer');roomNodes=[];
 for(const obj of objects){const label=obj.type==='machine'&&currentRoom==='suite'?'<g><rect x="-23" y="-134" width="46" height="18" rx="9" fill="#173c3c" stroke="#c5ad76" stroke-width=".7"/><text x="0" y="-122" text-anchor="middle" fill="#e6d19a" font-size="8" letter-spacing="1">PLAY</text></g>':'';const node=svgNode(objectArt(obj,state.favourite)+label);node.dataset.object=obj.id;node.setAttribute('role','button');node.setAttribute('tabindex','0');node.setAttribute('aria-label',obj.type==='boutique'?'Open the cosmetic boutique':CATALOG[obj.type]?.name||obj.type);node.setAttribute('transform',`translate(${project(obj.x,obj.y)})`);depthLayer.append(node);const [w,d]=dimensions(obj);roomNodes.push({node,obj,depth:obj.x+obj.y+(w+d)/2});}
 hero=svgNode(avatarArt(state)+`<text class="guest-name" y="-106">${esc(state.name)} <tspan fill="#d4c38f" font-size="7">YOU</tspan></text><path d="M-4-99 0-95 4-99" fill="#cfbe88"/>`);hero.id='player';depthLayer.append(hero);
 for(const npc of npcs){npc.node=svgNode(`<g class="resident-visual">${avatarArt(npc,true)}</g><text class="guest-name" y="-114">${esc(npc.name)} <tspan font-size="6" fill="#9eb5a6">NPC</tspan></text><text class="resident-state" y="-102" text-anchor="middle" fill="#b8cab0" font-size="6.5"></text><g class="bubble" style="display:none"><rect x="-83" y="-166" width="166" height="37" rx="8" fill="#e0dcc3"/><path d="m-4-130 4 6 4-6" fill="#e0dcc3"/><text class="bubble-text" text-anchor="middle" font-size="8" fill="#244342"></text></g>`);npc.renderMode=npc.mode;npc.renderSpeech=null;npc.node.dataset.npc=npc.id;npc.node.setAttribute('role','button');npc.node.setAttribute('tabindex','0');npc.node.setAttribute('aria-label',`Talk to ${npc.name}, ${npc.title}`);depthLayer.append(npc.node);}
 updateActors();drawGhost();
}
function speechLines(text){const words=text.split(/\s+/),lines=[''];for(const word of words){if((lines.at(-1)+' '+word).trim().length>32&&lines.length<2)lines.push('');lines[lines.length-1]+=(lines.at(-1)?' ':'')+word;}return lines.map(x=>x.length>34?x.slice(0,31)+'…':x);}
function updateActors(){
 const moving=path.length>0||stick.active&&Math.hypot(stick.x,stick.y)>.1||keys.size>0;const [px,py]=project(player.x,player.y);hero.setAttribute('transform',`translate(${px.toFixed(2)} ${py.toFixed(2)})`);hero.classList.toggle('walking',moving&&!editing&&!panel.open);const order=[...roomNodes,{node:hero,depth:player.x+player.y}];
 const speaking=new Set(npcs.filter(n=>n.speechUntil>hotel.time).sort((a,b)=>b.speechUntil-a.speechUntil).slice(0,2).map(n=>n.id));for(const npc of npcs){const [x,y]=project(npc.x,npc.y);npc.node.setAttribute('transform',`translate(${x.toFixed(2)} ${y.toFixed(2)})`);npc.node.classList.toggle('walking',npc.path.length>0);npc.node.classList.toggle('playing-music',npc.mode==='music');npc.node.classList.toggle('skating',npc.mode==='skating');npc.node.dataset.state=npc.mode;if(npc.renderMode!==npc.mode){npc.node.querySelector('.resident-visual').innerHTML=avatarArt(npc,true);npc.renderMode=npc.mode;}const status=npc.node.querySelector('.resident-state'),description=hotel.describe(npc);if(status.textContent!==description)status.textContent=description;
 const bubble=npc.node.querySelector('.bubble');bubble.style.display=speaking.has(npc.id)?'block':'none';if(npc.renderSpeech!==npc.speech){npc.node.querySelector('.bubble-text').innerHTML=speechLines(npc.speech).map((line,i)=>`<tspan x="0" y="${-151+i*12}">${esc(line)}</tspan>`).join('');npc.renderSpeech=npc.speech;}order.push({node:npc.node,depth:npc.x+npc.y});}
 for(const {node,obj}of roomNodes)if(obj.type==='machine')node.classList.toggle('cabinet-in-use',npcs.some(a=>a.mode==='betting'&&a.machine===obj.id));
 order.sort((a,b)=>a.depth-b.depth);for(let i=0;i<order.length;i++)if(depthLayer.children[i]!==order[i].node)depthLayer.insertBefore(order[i].node,depthLayer.children[i]||null);
}
function processResidentEvents(){for(const event of hotel.drain()){const log=roomChatLogs[event.room];log.push({...event,target:event.targetId!==null?GUESTS[event.targetId]?.name:null});if(log.length>40)log.splice(0,log.length-40);}if(panelType==='chat'&&$('#chat-log')){const log=$('#chat-log'),markup=chatMarkup();if(log.innerHTML!==markup){log.innerHTML=markup;log.scrollTop=log.scrollHeight;}}}

function updateCamera(dt){const rect=game.getBoundingClientRect(),mobile=rect.width<600,landscape=rect.height<420;let scale;if(fit){scale=Math.min((rect.width-25)/800,(rect.height-(landscape?90:120))/640)*zoom;}else{scale=(mobile?.88:Math.min(rect.width/950,rect.height/720))*zoom;if(landscape)scale=Math.min(rect.width/850,rect.height/570)*zoom;}scale=Math.max(.28,scale);const vw=rect.width/scale,vh=rect.height/scale;const [px,py]=project(player.x,player.y);const tx=fit||vw>704?500:Math.max(148+vw/2,Math.min(852-vw/2,px)),ty=fit?370:Math.max(320,Math.min(410,py-100));const ease=Math.min(1,dt*5);camera.x+=(tx-camera.x)*ease;camera.y+=(ty-camera.y)*ease;world.setAttribute('viewBox',`${(camera.x-vw/2).toFixed(2)} ${(camera.y-vh/2).toFixed(2)} ${vw.toFixed(2)} ${vh.toFixed(2)}`);}
function markTarget(x,y){const p=project(x+.5,y+.5);targetLayer.innerHTML=`<g class="target-marker" transform="translate(${p})"><path d="M-19 0 0-9 19 0 0 9Z" fill="#d9ce9f22" stroke="#e8d49b" stroke-width="1.5"/><circle r="2" fill="#f2dfb0"/></g>`;}
function routeTo(tx,ty,callback){const route=pathfind([Math.floor(player.x),Math.floor(player.y)],[tx,ty],objects);if(route===null){notice('That spot is blocked. Try an open tile.');return false;}path=[{x:Math.floor(player.x)+.5,y:Math.floor(player.y)+.5},...route.map(([x,y])=>({x:x+.5,y:y+.5}))];onArrival=callback||null;markTarget(tx,ty);return true;}
function routeObject(obj){const a=approach(player,obj,objects);if(!a){notice('Make a little space to reach this object.');return;}routeTo(...a.target,()=>interact(obj));}
function interact(obj){if(obj.type==='boutique')openStore();else if(obj.type==='machine')openSlot(obj.game||state.favourite);else if(obj.type==='sign')openHotel();else if(obj.type==='bar')toast(currentRoom==='lobby'?'Welcome to The Grand. Your suite is on floor four.':'Something sparkling? The city is the main attraction.');else if(obj.type==='speaker'){state.sound=!state.sound;save();toast(state.sound?'Sound on. A little atmosphere.':'Sound off.');tone(440,.2);}else if(obj.type==='bed')toast('A room of your own. Tap Decorate to make it yours.');else if(obj.type==='sofa'||obj.type==='chair'){toast('Your favourite spot. Take a moment.');tone(330,.14);}else toast(CATALOG[obj.type]?.desc||'A small detail that makes the room.');}
function stepPath(actor,dt,speed=2.7){if(!actor.path.length)return false;const dest=actor.path[0],dx=dest.x-actor.x,dy=dest.y-actor.y,len=Math.hypot(dx,dy),step=dt*speed;if(len<=step){actor.x=dest.x;actor.y=dest.y;actor.path.shift();return true;}actor.x+=dx/len*step;actor.y+=dy/len*step;return false;}
function loop(time){const dt=Math.min(.04,lastTime?(time-lastTime)/1000:.016);lastTime=time;elapsed+=dt;frame++;if(!editing&&!panel.open){let sx=stick.x,sy=stick.y;if(keys.has('ArrowLeft')||keys.has('a'))sx-=1;if(keys.has('ArrowRight')||keys.has('d'))sx+=1;if(keys.has('ArrowUp')||keys.has('w'))sy-=1;if(keys.has('ArrowDown')||keys.has('s'))sy+=1;if(Math.hypot(sx,sy)>.12){path=[];onArrival=null;targetLayer.innerHTML=''; // Screen-space input -> isometric tile axes.
 const isoX=sx+sy*2,isoY=sy*2-sx;player=moveContinuous(player,isoX,isoY,dt,objects);
 }else if(path.length){const actor={...player,path};stepPath(actor,dt);player={x:actor.x,y:actor.y};path=actor.path;if(!path.length){targetLayer.innerHTML='';const fn=onArrival;onArrival=null;fn?.();}}}
 hotel.tick(dt);if((panelType==='guest'||panelType==='chat')&&chatTarget!==null)hotel.hold(chatTarget);processResidentEvents();updateActors();if(frame%120===0)updateSidebar();updateCamera(dt);requestAnimationFrame(loop);}
function point(event){const pt=world.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;return pt.matrixTransform(world.getScreenCTM().inverse());}
let down=null;
world.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};const r=game.getBoundingClientRect();if(e.pointerType==='touch'&&state.joystick==='floating'&&!editing&&!panel.open&&e.clientX-r.left<r.width*.45&&e.clientY-r.top>r.height*.63&&!e.target.closest('[data-object],[data-npc],[data-exit]')){const stickEl=$('#joystick');const cx=Math.max(52,Math.min(r.width-52,e.clientX-r.left)),cy=Math.max(80,Math.min(r.height-65,e.clientY-r.top));stickEl.style.left=`${cx-47}px`;stickEl.style.top=`${cy-47}px`;stickEl.style.bottom='auto';startStick(e,true);}});
world.addEventListener('pointermove',e=>{if(stick.active)return;if(editing&&selection){const p=point(e),[x,y]=unproject(p.x,p.y);previewAt(Math.floor(x),Math.floor(y));}});
world.addEventListener('pointerup',e=>{if(stick.active)return;if(!down||Math.hypot(down.x-e.clientX,down.y-e.clientY)>15)return;down=null;const object=e.target.closest('[data-object]'),npc=e.target.closest('[data-npc]'),exit=e.target.closest('[data-exit]');if(editing){if(object&&!selection){selectExisting(object.dataset.object);return;}const p=point(e),[x,y]=unproject(p.x,p.y);if(selection)previewAt(Math.floor(x),Math.floor(y));else if(object)selectExisting(object.dataset.object);else notice('Choose furniture below, then tap a floor tile.');return;}if(object){routeObject(objects.find(o=>o.id===object.dataset.object));return;}if(npc){const n=hotel.engage(Number(npc.dataset.npc));routeTo(Math.floor(n.x),Math.floor(n.y),()=>openGuest(n.id));return;}if(exit){routeTo(...ROOMS[currentRoom].exit,openHotel);return;}const p=point(e),[x,y]=unproject(p.x,p.y),tx=Math.floor(x),ty=Math.floor(y);if(tx===7&&ty===7)routeTo(tx,ty,openHotel);else if(tx>=0&&ty>=0&&tx<8&&ty<8)routeTo(tx,ty);});
world.addEventListener('keydown',e=>{if(panel.open||editing)return;if(e.key==='Enter'||e.key===' '){const o=e.target.closest('[data-object]'),n=e.target.closest('[data-npc]'),exit=e.target.closest('[data-exit]');if(o){e.preventDefault();routeObject(objects.find(x=>x.id===o.dataset.object));}else if(n){e.preventDefault();openGuest(Number(n.dataset.npc));}else if(exit){e.preventDefault();routeTo(...ROOMS[currentRoom].exit,openHotel);}}});
function startStick(e,dynamic=false){if(editing||panel.open)return;e.preventDefault();e.stopPropagation();stick={x:0,y:0,active:true,id:e.pointerId,fromWorld:dynamic===true,startX:e.clientX,startY:e.clientY,moved:false};$('#joystick').classList.add('active');$('#joystick').setPointerCapture(e.pointerId);path=[];onArrival=null;targetLayer.innerHTML='';moveStick(e);}
function moveStick(e){if(!stick.active||e.pointerId!==stick.id)return;if(Math.hypot(e.clientX-stick.startX,e.clientY-stick.startY)>8)stick.moved=true;const r=$('#joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,max=r.width*.3,mag=Math.hypot(dx,dy),m=Math.min(1,mag/max);stick.x=mag?dx/mag*m:0;stick.y=mag?dy/mag*m:0;$('.stick-thumb').style.transform=`translate(${stick.x*max}px,${stick.y*max}px)`;}
function stopStick(event){const tap=event?.type==='pointerup'&&stick.fromWorld&&!stick.moved;const tapPoint=tap?{clientX:stick.startX,clientY:stick.startY}:null;stick.fromWorld=false;stick.active=false;stick.x=0;stick.y=0;$('#joystick').classList.remove('active');$('.stick-thumb').style.transform='';$('#joystick').style.left='';$('#joystick').style.top='';$('#joystick').style.bottom='';if(tapPoint){const p=point(tapPoint),[x,y]=unproject(p.x,p.y);const tx=Math.floor(x),ty=Math.floor(y);if(tx>=0&&ty>=0&&tx<8&&ty<8)routeTo(tx,ty,tx===7&&ty===7?openHotel:null);}}
$('#joystick').addEventListener('pointerdown',startStick);$('#joystick').addEventListener('pointermove',moveStick);$('#joystick').addEventListener('pointerup',stopStick);$('#joystick').addEventListener('pointercancel',stopStick);$('#joystick').addEventListener('lostpointercapture',stopStick);
function applyControls(){$('#joystick').classList.toggle('floating',state.joystick==='floating');$('#joystick').classList.toggle('persistent',state.joystick==='persistent');}
window.addEventListener('keydown',e=>{if(panel.open||editing||e.ctrlKey||e.metaKey)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys.add(e.key);}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>{keys.clear();stopStick();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();stopStick();save();}});
function beginEdit(){if(currentRoom!=='suite'){openHotel();return;}editing=!editing;game.classList.toggle('edit-mode',editing);$('#editbar').hidden=!editing;path=[];onArrival=null;selection=null;ghost=null;stopStick();targetLayer.innerHTML='';if(editing){notice('Tap existing furniture to move it, or add something below.');renderEditbar();}else{drawScene();$('.edit-button').innerHTML=icon('edit',16)+'<span>Decorate</span>';}}
function renderEditbar(){$('#editbar').innerHTML=`<div class="edit-tools"><span>${selection?esc(CATALOG[selection.type].name):'Choose a piece. Make it yours.'}</span>${selection?`<button data-action="edit-cancel" aria-label="Cancel furniture selection">${icon('close',14)}</button><button data-action="edit-rotate" aria-label="Rotate furniture">${icon('rotate',15)}</button>${objects.some(o=>o.id===selection.id)?`<button data-action="edit-remove" aria-label="Remove selected furniture">${icon('trash',15)}</button>`:''}<button data-action="edit-place" ${!ghostValid?'disabled':''}>Place here</button>`:`<button data-action="style">Style & games</button>`}<button class="done" data-action="edit-done">Done</button></div><div class="inventory">${Object.entries(CATALOG).map(([type,c])=>`<button class="${selection?.type===type?'active':''}" data-action="edit-add" data-type="${type}" aria-label="Add ${c.name}">${objectSvg({type,rot:0},state.favourite)}<span>${c.name}</span></button>`).join('')}</div>`;}
function selectExisting(id){selection={...objects.find(o=>o.id===id)};ghost={...selection};ghostValid=true;renderEditbar();drawGhost();notice('Tap an open tile to preview the new position.');}
function previewAt(x,y){if(!selection)return;ghost={...selection,x,y};ghostValid=canPlace(ghost,objects,player);drawGhost();const b=$('[data-action="edit-place"]');if(b)b.disabled=!ghostValid;}
function drawGhost(){if(!ghostLayer)return;if(!ghost){ghostLayer.innerHTML='';return;}const [w,d]=dimensions(ghost),p=project,color=ghostValid?'#b5dcaa':'#e59886';let s='';for(let x=ghost.x;x<ghost.x+w;x++)for(let y=ghost.y;y<ghost.y+d;y++)s+=`<polygon points="${[p(x,y),p(x+1,y),p(x+1,y+1),p(x,y+1)].map(a=>a.join(',')).join(' ')}" fill="${color}55" stroke="${color}"/>`;const pos=p(ghost.x,ghost.y);ghostLayer.innerHTML=s+`<g transform="translate(${pos})" opacity=".65" pointer-events="none">${objectArt(ghost,state.favourite)}</g>`;}
function placeSelected(){if(!ghost||!canPlace(ghost,objects,player)){notice('Choose a clear tile with a route to the hotel exit.');return;}const i=objects.findIndex(o=>o.id===ghost.id);if(i>=0)objects[i]={...ghost};else if(objects.length<24)objects.push({...ghost});else{notice('Your suite is full. Remove a piece before adding another.');return;}state.furniture=objects;state.decorated++;selection=null;ghost=null;ghostValid=false;drawScene();renderEditbar();updateProgress();notice('Looking more like you. Room saved.');}
function showPanel(type,content){if(spinning)return;panelType=type;keys.clear();stopStick();path=[];onArrival=null;targetLayer.innerHTML='';$('#panel-content').innerHTML=`<div class="panel-inner">${content}</div>`;if(!panel.open)panel.showModal();panel.scrollTop=0;}
function closePanel(){if(chatTarget!==null){const a=hotel.get(chatTarget);if(a?.partner==='player')hotel.release(a);}if(spinning){toast('Your round is finishing.');return;}if(panel.open)panel.close();panelType='';navActive(currentRoom==='suite'?'suite':'hotel');}
const panelHeader=(eyebrow,title,desc='')=>`<div class="panel-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div><button class="close-button" data-action="close" aria-label="Close menu">${icon('close',18)}</button></div>`;
function miniRoom(id){const r=ROOMS[id],s=roomArt(r,state).replaceAll(/data-[a-z-]+="[^"]*"/g,'');const obs=(id==='suite'?state.furniture:r.objects).map(o=>{const p=project(o.x,o.y);return`<g transform="translate(${p})">${objectArt(o,state.favourite)}</g>`;}).join('');return `<svg viewBox="70 45 860 660" aria-hidden="true">${s}${obs}</svg>`;}
function openHotel(){showPanel('hotel',panelHeader('THE HOTEL DIRECTORY','Where to this evening?','Four different moods. One place to belong.')+`<button class="suite-shortcut" data-action="go-room" data-room="suite">${icon('suite',25)}<div><strong>Your private suite</strong><small>Floor 04 · Your home at The Grand</small></div>${icon('arrow',18)}</button><div class="hotel-grid">${['lobby','gold','neon','roof'].map((id,i)=>{const r=ROOMS[id];return `<button class="hotel-card" data-action="go-room" data-room="${id}"><div class="room-mini">${miniRoom(id)}</div><span class="room-number">${['G','01','02','08'][i]}</span><div class="card-body"><strong>${r.short}</strong><small>${r.guestCount} RESIDENTS · ${id==='roof'?'CITY VIEWS':id==='lobby'?'MEET & EXPLORE':id==='gold'?'CLASSIC GAMES':'NOVA GAMES'}</small></div></button>`;}).join('')}</div><p class="panel-note">Meet 20 original adult residents with their own routines. They are simulated characters. Tap a guest to say hello, or walk to a machine to play with virtual credits.</p>`);navActive('hotel');}
function openAvatar(){showPanel('avatar',panelHeader('YOUR IDENTITY','A look of your own.','A few small details. A little more you.')+`<label class="field-label" for="name-input">DISPLAY NAME</label><input id="name-input" class="text-field" maxlength="18" value="${esc(state.name)}" autocomplete="off"><div class="wardrobe-preview">${avatarSvg(state)}<span class="preview-caption">LIVE PREVIEW</span></div><section class="identity-section"><h3>Your avatar</h3><div class="segmented identity-options">${PRESENTATIONS.map(p=>`<button data-action="appearance" data-field="presentation" data-value="${p.id}" class="${state.presentation===p.id?'active':''}" aria-pressed="${state.presentation===p.id}">${p.name}</button>`).join('')}</div><h3>Skin tone</h3><div class="skin-options">${SKIN_TONES.map((color,i)=>`<button style="--skin:${color}" class="skin-option ${state.skin===color?'selected':''}" data-action="appearance" data-field="skin" data-value="${color}" aria-label="Skin tone ${i+1}" aria-pressed="${state.skin===color}">${state.skin===color?icon('check',17):''}</button>`).join('')}</div><h3>Hairstyle</h3><div class="hair-options">${HAIR_STYLES.map(h=>`<button data-action="appearance" data-field="hairStyle" data-value="${h.id}" class="${state.hairStyle===h.id?'selected':''}" aria-pressed="${state.hairStyle===h.id}"><svg viewBox="-32 -115 64 95" aria-hidden="true">${avatarArt({...state,hairStyle:h.id,hat:'none'})}</svg><span>${h.name}</span></button>`).join('')}</div><p class="panel-note">Avatar style, skin tones and hairstyles are always free.</p></section><button class="store-shortcut" data-action="store">${icon('store',20)} Browse the cosmetic boutique <span>→</span></button>${Object.entries(COSMETICS).map(([category,items])=>`<section class="wardrobe-category"><h3>${{shirt:'Your wardrobe',hair:'Hair colour',hat:'Headwear',accessory:'The finishing touch'}[category]}</h3><div class="cosmetic-grid">${items.map(c=>{const unlocked=isUnlocked(c,state);return `<button class="cosmetic ${state[category]===c.id?'selected':''} ${unlocked?'':'locked'}" data-action="equip" data-category="${category}" data-id="${c.id}" aria-label="${esc(c.name)}${unlocked?'':', locked'}" aria-pressed="${state[category]===c.id}">${c.color?`<span class="color-swatch" style="background:${c.color}"></span>`:icon(category==='hat'?'avatar':'star',16)}<span>${c.name}${!unlocked?`<small class="locked-label">${esc(c.price?`${c.price} credits · Boutique`:ACHIEVEMENTS.find(a=>a.id===c.achievement)?.desc||'')}</small>`:''}</span>${!unlocked?`<span class="lock-icon">${icon('lock',12)}</span>`:''}</button>`;}).join('')}</div></section>`).join('')}<p class="panel-note">Changes are saved as you go and appear in every hotel room.</p>`);navActive('avatar');}
function openRewards(){showPanel('rewards',panelHeader('LITTLE THINGS, WELL EARNED','A stay with a story.','Explore, play, make yourself at home.')+`<div class="progress-summary">${icon('rewards',27)}<strong>${state.unlocked.length}<span> / 6</span></strong><span>achievements complete<br>Cosmetics are yours to keep.</span></div>${ACHIEVEMENTS.map(a=>{const p=Math.min(progress(a,state),a.target),done=state.unlocked.includes(a.id);return `<div class="achievement ${done?'done':''}"><div class="achievement-badge">${icon(done?'check':a.demo?'coin':'star',19)}</div><div><h3>${a.name}${a.demo?'<span class="demo-chip">SIMULATED</span>':''}</h3><p>${a.desc}</p><p class="reward-text">${done?'Unlocked':'Unlocks'} · ${a.reward}</p><div class="progress"><span style="width:${p/a.target*100}%"></span></div><div class="progress-meta"><span>${done?'COMPLETE':a.demo?'DEMO ONLY':'IN PROGRESS'}</span><span>${p} / ${a.target}</span></div>${a.demo&&!done?'<button class="text-button" style="margin-top:12px" data-action="wallet">Try the funding demo →</button>':''}</div></div>`;}).join('')}<button class="primary wide" data-action="avatar">Open your wardrobe ${icon('arrow',16)}</button>`);navActive('rewards');}
function openSettings(){showPanel('settings',panelHeader('THE FINER DETAILS','Your preferences.')+`<div class="settings-row"><div><strong>Touch joystick</strong><p>Floating: starts where you touch<br>in the lower-left of the world.</p></div><div class="segmented"><button data-action="joystick" data-mode="floating" class="${state.joystick==='floating'?'active':''}">Floating</button><button data-action="joystick" data-mode="persistent" class="${state.joystick==='persistent'?'active':''}">Fixed</button></div></div><div class="settings-row"><div><strong>Game sounds</strong><p>A small sound for spins and unlocks.</p></div><button class="secondary" data-action="sound">${icon(state.sound?'sound':'mute',17)} ${state.sound?'On':'Off'}</button></div><div class="settings-row"><div><strong>Camera</strong><p>Follow your avatar or view the whole room.</p></div><button class="secondary" data-action="fit">${fit?'Following':'Fit room'}</button></div><p class="settings-footer">Tap an open floor tile to walk. Tap a machine to approach and play. On desktop, use WASD or arrow keys. Use + and − to adjust the view.<br><br>Progress saves in this browser. ${storageOK?'Local saving is available.':'Local saving is unavailable.'}<br><br>18+ concept prototype. All credits are fictional and have no monetary value. All guests and conversations are simulated. No real-money payments or prizes.</p>`);}
function openWallet(){showPanel('wallet',panelHeader('VIRTUAL CREDIT WALLET','A little play money.','Everything here is a demonstration.')+`<div class="wallet-summary"><strong>${state.credits.toLocaleString()}</strong><span>VIRTUAL CREDITS</span><p>No monetary value. No withdrawal.<br>Real payments are not supported.</p></div><div class="wallet-actions"><button class="quiet-button" data-action="refill" ${canRefill(state)?'':'disabled'}>Add ${REFILL_AMOUNT.toLocaleString()} free credits</button>${canRefill(state)?'':`<p class="panel-note">Free top-ups open when your balance drops below ${REFILL_BELOW} credits.</p>`}</div><div class="fund-demo"><h3>Try the funding reward ${'<span class="demo-chip">SIMULATED</span>'}</h3><p>Preview a one-time welcome cosmetic unlock. This adds fictional credits and unlocks the Champagne jacket. No card details or payments.</p><button class="primary wide" data-action="fund" ${state.funded?'disabled':''}>${state.funded?'Welcome collection unlocked':'Simulate funding · 1,000 credits'}</button></div><p class="panel-note">This is a cosmetic-flow demo, with no streaks or spending targets.</p>`);}
function openStyle(){showPanel('style',panelHeader('SUITE 408','Set the atmosphere.','Your room, down to the details.')+`<div class="wardrobe-category"><h3>Wall palette</h3><div class="cosmetic-grid">${[['evergreen','Evergreen','#37736a'],['rose','Dusty rose','#805d63'],['midnight','Midnight blue','#40516c']].map(([id,name,color])=>`<button class="cosmetic ${state.theme===id?'selected':''}" data-action="theme" data-theme="${id}"><span class="color-swatch" style="background:${color}"></span>${name}</button>`).join('')}</div></div><div class="wardrobe-category"><h3>Underfoot</h3><div class="cosmetic-grid">${[['oak','Warm parquet','#b2946e'],['stone','Limestone','#a9afa5']].map(([id,name,color])=>`<button class="cosmetic ${state.floor===id?'selected':''}" data-action="floor" data-floor="${id}"><span class="color-swatch" style="background:${color}"></span>${name}</button>`).join('')}</div></div><div class="wardrobe-category"><h3>Your favourite machine</h3><div class="game-choice">${['gold','neon'].map(id=>`<button class="quiet-button ${state.favourite===id?'active':''}" data-action="favourite" data-game="${id}">${id==='gold'?'Grand Sevens':'Nova Nights'}</button>`).join('')}</div></div><p class="panel-note">Your favourite changes every cabinet in your suite. Everything saves automatically.</p><button class="primary wide" data-action="close">Back to your room ${icon('arrow',16)}</button>`);}
function markAcquaintance(id){const first=!state.metResidents.includes(id);if(first)state.metResidents.push(id);state.friendship[id]=(state.friendship[id]||0)+1;state.social++;updateProgress();return !first;}
function openPeople(){showPanel('people',panelHeader('THE HOTEL’S REGULARS','Twenty stories to meet.',`${state.metResidents.length} of 20 residents met. Tap a face to get acquainted.`)+`<div class="resident-directory">${GUESTS.map(g=>{const a=hotel.get(g.id);return `<button class="resident-card" data-action="guest" data-index="${g.id}"><div class="resident-portrait">${guestSvg(g)}</div><div><strong>${g.fullName}</strong><span>${g.title}</span><small>${ROOMS[g.room].short} · ${esc(hotel.describe(a))}</small><em>${state.metResidents.includes(g.id)?'Acquainted':'Not met yet'}</em></div>${icon('arrow',15)}</button>`;}).join('')}</div><p class="panel-note">All residents are original adult fictional characters, driven by scripted routines. No connected human players are shown.</p>`);}
function openGuest(index){const g=GUESTS.find(x=>x.id===Number(index));if(!g)return;chatTarget=g.id;const a=hotel.engage(g.id);showPanel('guest',panelHeader('A REGULAR AT THE GRAND',g.fullName)+`<div class="resident-profile"><div class="profile-hero">${guestSvg(g)}<span class="demo-chip">SIMULATED RESIDENT · AGE ${g.age}</span></div><div><h3>${g.title}</h3><p>${g.bio}</p><div class="resident-location">${ROOMS[g.room].short} · ${esc(hotel.describe(a))}</div></div></div><div class="profile-quote">“${esc(g.hello)}”</div><div class="topic-list">${g.topics.map((topic,i)=>`<button data-action="resident-topic" data-index="${g.id}" data-topic="${i}">${topic.label} ${icon('chat',15)}</button>`).join('')}</div><button class="primary wide" data-action="say-hello" data-index="${g.id}">${state.metResidents.includes(g.id)?'Catch up':'Introduce yourself'} ${icon('chat',17)}</button>${currentRoom!==g.room?`<button class="quiet-button wide" data-action="go-room" data-room="${g.room}">Visit ${ROOMS[g.room].short}</button>`:''}<p class="panel-note">${state.metResidents.includes(g.id)?`You’ve spoken ${state.friendship[g.id]||0} times.`:'Your first conversation is still ahead.'} Replies are written for this character; routines and conversations run locally.</p>`);}
function updateChatDefaults(){const log=roomChatLogs[currentRoom];if(!log.length)for(const a of npcs.slice(0,2))log.push({who:a.name,text:a.ambient[0],index:a.id,target:null});chatMessages=log;}
function chatMarkup(){return roomChatLogs[currentRoom].map(m=>`<div class="chat-message"><div class="guest-portrait">${m.index===-1?avatarSvg(state):guestSvg(GUESTS[m.index])}</div><div><strong>${esc(m.who)}</strong><small>${m.index===-1?'YOU':m.target?'TO '+esc(m.target):'SIMULATED RESIDENT'}</small><p>${esc(m.text)}</p></div></div>`).join('');}
function openChat(){const g=chatTarget!==null?GUESTS[chatTarget]:null;showPanel('chat',panelHeader(g?'CONVERSATION':'ROOM CONVERSATION',g?g.name:ROOMS[currentRoom].short,g?g.title:'Residents talk here while they go about their evening.')+`<div id="chat-log" class="chat-log" aria-live="polite">${chatMarkup()}</div><div class="chat-targets"><button data-action="chat-target" data-index="room" class="${!g?'selected':''}">Room</button>${npcs.map(a=>`<button data-action="chat-target" data-index="${a.id}" class="${g?.id===a.id?'selected':''}">${a.name}</button>`).join('')}</div><div class="chat-suggestions"><button data-action="chat-quick" data-message="Evening, everyone!">Evening, everyone!</button>${g?g.topics.map((topic,i)=>`<button data-action="resident-topic" data-index="${g.id}" data-topic="${i}">${topic.label}</button>`).join(''):'<button data-action="chat-quick" data-message="Where should I explore?">Where should I explore?</button>'}</div><form class="chat-form" id="chat-form"><input class="text-field" id="chat-input" placeholder="${g?'Ask '+g.name+' something…':'Say something to the room…'}" maxlength="160" aria-label="Chat message" autocomplete="off"><button class="primary" aria-label="Send demo chat message">${icon('arrow',19)}</button></form><p class="panel-note">Original scripted characters · routines continue while you talk.</p>`);const log=$('#chat-log');log.scrollTop=log.scrollHeight;}
function sendChat(text,topicIndex=null){text=text.trim().slice(0,160);if(!text)return;const id=chatTarget??npcs[0]?.id??0,g=GUESTS[id],familiar=state.metResidents.includes(id);roomChatLogs[currentRoom].push({who:state.name,text,index:-1,target:g.name});markAcquaintance(id);const reply=residentReply(g,text,{name:state.name,familiar},topicIndex);roomChatLogs[currentRoom].push({who:g.name,text:reply,index:id,target:state.name});chatTarget=id;const a=hotel.engage(id);hotel.say(a,reply);hotel.drain();if(roomChatLogs[currentRoom].length>40)roomChatLogs[currentRoom].splice(0,roomChatLogs[currentRoom].length-40);openChat();}
function openStore(){const items=STORE_ITEMS.filter(c=>storeFilter==='all'||c.category===storeFilter||storeFilter==='owned'&&state.owned.includes(c.id));showPanel('store',panelHeader('THE GRAND BOUTIQUE','Find your finishing touch.','Optional cosmetics, bought with fictional game credits.')+`<div class="store-balance">${icon('coin',21)}<strong>${state.credits.toLocaleString()}</strong><span>virtual credits</span><em>${state.owned.length} items owned</em></div><div class="store-tabs">${[['all','All items'],['shirt','Jackets'],['hat','Hats'],['accessory','Accessories'],['owned','Owned']].map(([id,label])=>`<button class="${storeFilter===id?'selected':''}" data-action="store-filter" data-filter="${id}">${label}</button>`).join('')}</div><div class="store-grid">${items.map(item=>`<button class="store-item" data-action="shop-item" data-id="${item.id}"><div class="item-preview">${avatarSvg({...state,[item.category]:item.id})}</div><strong>${item.name}</strong><span>${state.owned.includes(item.id)?'Owned · wear it':item.price+' credits'}</span><small>Try on ${icon('arrow',12)}</small></button>`).join('')}</div>${!items.length?'<p class="empty-store">Your collection starts with something you love. Browse the boutique to try a piece.</p>':''}<p class="panel-note">No real money. Owned items stay in your wardrobe. Your avatar style, skin tone and all eight hairstyles are free.</p>`);}
function openStoreItem(id){const item=STORE_ITEMS.find(c=>c.id===id);if(!item)return;const owned=state.owned.includes(id),affordable=state.credits>=item.price;showPanel('store-item',panelHeader('THE GRAND BOUTIQUE',item.name)+`<div class="wardrobe-preview store-tryon">${avatarSvg({...state,[item.category]:id})}<span class="preview-caption">TRYING ON · YOUR AVATAR</span></div><p class="item-description">${item.desc}</p><div class="item-price"><strong>${owned?'Owned':item.price.toLocaleString()+' credits'}</strong><span>Your balance: ${state.credits.toLocaleString()} virtual credits</span></div><button class="primary wide" data-action="${owned?'store-equip':'purchase'}" data-id="${id}" ${!owned&&!affordable?'disabled':''}>${owned?'Wear this item':'Buy & wear · '+item.price+' credits'}</button>${!owned&&!affordable?'<p class="funds-note">You need more virtual credits for this item.</p><button class="quiet-button wide" data-action="wallet">Open your virtual-credit wallet</button>':''}<button class="text-button store-back" data-action="store">← Back to the boutique</button><p class="panel-note">${owned?'Wearing this item does not spend credits.':affordable?'After purchase: '+(state.credits-item.price).toLocaleString()+' credits.':''} Credits have no monetary value.</p>`);}

function openSlot(id){activeGame=id==='neon'?'neon':'gold';const neon=activeGame==='neon';showPanel('slot',panelHeader('VIRTUAL CREDIT GAME',neon?'Nova Nights':'Grand Sevens')+`<div class="slot-panel ${neon?'neon':''}"><div class="slot-title">${neon?'NOVA NIGHTS':'GRAND SEVENS'}</div><div class="slot-subtitle">${neon?'A LITTLE COSMIC GOOD FORTUNE':'AN ORIGINAL AT THE GRAND'}</div><div class="reels">${(neon?['orb','bolt','star']:['seven','diamond','crown']).map(s=>`<div class="reel">${symbolSvg(s)}</div>`).join('')}</div><div class="slot-message" aria-live="polite">Settle in. See where the reels take you.</div><div class="slot-details"><span>ROUND · 25 CREDITS</span><span class="slot-balance">BALANCE · ${state.credits.toLocaleString()}</span></div><button class="primary spin-button" data-action="spin" ${state.credits<25?'disabled':''}>SPIN · 25 CREDITS ${icon('rotate',16)}</button></div><div class="slot-info">Virtual credits only. No monetary value. Outcomes are simulated.<br>Play at your own pace. Close whenever you like.</div><details class="paytable"><summary>How this demo pays</summary>${paytableLines(activeGame).join('<br>')}<br>Other combinations · 0 · ${+((1-HIT_RATE)*100).toFixed(1)}%<br>Return to player ≈ ${Math.round(RTP*100)}%. Over time, the house keeps a little.<br>Payout includes the round cost. This prototype is not a certified game.</details>${currentRoom==='suite'?`<div class="game-choice">${['gold','neon'].map(game=>`<button class="quiet-button ${activeGame===game?'active':''}" data-action="slot-choice" data-game="${game}">${game==='gold'?'Grand Sevens':'Nova Nights'}</button>`).join('')}</div>`:''}${state.credits<25?'<button class="quiet-button" style="width:100%;margin-top:15px" data-action="wallet">Get free demo credits</button>':''}`);}
function startSpin(){if(spinning)return;const outcome=spin(state,activeGame);if(!outcome){openWallet();return;}spinning=true;save();const button=$('[data-action="spin"]');button.disabled=true;button.textContent='SPINNING…';$('.reels').classList.add('spinning');$('.slot-message').textContent='';tone(260,.08);let i=0;const symbols=activeGame==='neon'?['orb','bolt','star','diamond']:['seven','diamond','crown','cherry'];spinTimer=setInterval(()=>{$$('.reel').forEach((r,k)=>r.innerHTML=symbolSvg(symbols[(i+k)%4]));i++;},95);setTimeout(()=>{clearInterval(spinTimer);$$('.reel').forEach((r,k)=>r.innerHTML=symbolSvg(outcome.symbols[k]));$('.reels')?.classList.remove('spinning');spinning=false;if(panelType==='slot'){$('.slot-message').textContent=outcome.payout?`${outcome.payout} credits returned · +${outcome.net} net`:'No match this round.';$('.slot-balance').textContent=`BALANCE · ${state.credits.toLocaleString()}`;button.disabled=state.credits<25;button.innerHTML='SPIN · 25 CREDITS '+icon('rotate',16);if(state.credits<25){button.parentElement.insertAdjacentHTML('afterend','<button class="quiet-button" style="width:100%;margin-top:12px" data-action="wallet">Get free demo credits</button>');}}updateProgress();if(outcome.payout)tone(660,.22);},1150);}
function tone(freq,duration){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.value=freq;gain.gain.setValueAtTime(.05,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+duration);}catch{}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;if(spinning&&a!=='spin')return;if(handleNewAction(a,button))return;switch(a){case 'suite':enterRoom('suite');break;case 'hotel':openHotel();break;case 'avatar':openAvatar();break;case 'rewards':openRewards();break;case 'settings':openSettings();break;case 'close':closePanel();break;case 'go-room':enterRoom(button.dataset.room);break;case 'wallet':openWallet();break;case 'refill':if(!refill(state)){toast(`Free top-ups open below ${REFILL_BELOW} credits.`);break;}save();openWallet();toast(`${REFILL_AMOUNT.toLocaleString()} free fictional credits added.`);break;case 'fund':if(!state.funded){state.funded=1;state.credits+=1000;updateProgress();openWallet();}break;case 'edit':beginEdit();break;case 'edit-done':beginEdit();break;case 'edit-add':selection={id:`f-${Date.now()}-${Math.floor(Math.random()*1000)}`,type:button.dataset.type,rot:0,x:4,y:4};ghost=null;ghostValid=false;renderEditbar();drawGhost();notice('Tap a floor tile, then Place here.');break;case 'edit-cancel':selection=null;ghost=null;ghostValid=false;renderEditbar();drawGhost();break;case 'edit-rotate':if(selection){selection.rot=selection.rot?0:1;if(ghost)previewAt(ghost.x,ghost.y);else drawGhost();}break;case 'edit-remove':if(selection){objects=objects.filter(o=>o.id!==selection.id);state.furniture=objects;selection=null;ghost=null;state.decorated++;drawScene();renderEditbar();updateProgress();notice('Piece returned to your inventory.');}break;case 'edit-place':placeSelected();break;case 'style':openStyle();break;case 'theme':state.theme=button.dataset.theme;styleChanged();break;case 'floor':state.floor=button.dataset.floor;styleChanged();break;case 'favourite':state.favourite=button.dataset.game;styleChanged();break;case 'slot-choice':state.favourite=button.dataset.game;save();drawScene();openSlot(button.dataset.game);break;case 'equip':{const c=COSMETICS[button.dataset.category].find(c=>c.id===button.dataset.id);if(!isUnlocked(c,state)){if(c.price){openStoreItem(c.id);break;}toast(`Unlock this: ${ACHIEVEMENTS.find(a=>a.id===c.achievement)?.desc}.`);break;}state[button.dataset.category]=c.id;save();drawScene();const scroll=panel.scrollTop;openAvatar();panel.scrollTop=scroll;break;}case 'joystick':state.joystick=button.dataset.mode;applyControls();save();openSettings();break;case 'sound':state.sound=!state.sound;save();tone(440,.1);if(panelType==='settings')openSettings();break;case 'fit':fit=!fit;zoom=1;if(panelType==='settings'){closePanel();toast(fit?'Whole room view. Tap fit again to follow your avatar.':'Camera follows your avatar.');}break;case 'zoom-in':zoom=Math.min(1.75,zoom+.15);break;case 'zoom-out':zoom=Math.max(.65,zoom-.15);break;case 'guest':openGuest(Number(button.dataset.index));break;case 'say-hello':chatTarget=Number(button.dataset.index);sendChat(`Hi, ${GUESTS[chatTarget].name}!`);break;case 'chat':chatTarget=null;openChat();break;case 'chat-quick':sendChat(button.dataset.message);break;case 'spin':startSpin();break;}});
function handleNewAction(action,button){
 if(action==='appearance'){const field=button.dataset.field,value=button.dataset.value,valid=field==='skin'?SKIN_TONES.includes(value):field==='presentation'?PRESENTATIONS.some(p=>p.id===value):field==='hairStyle'&&HAIR_STYLES.some(h=>h.id===value);if(valid){state[field]=value;save();drawScene();const scroll=panel.scrollTop;openAvatar();panel.scrollTop=scroll;}return true;}
 if(action==='people'){openPeople();return true;}
 if(action==='store'){openStore();return true;}
 if(action==='store-filter'){storeFilter=button.dataset.filter;openStore();return true;}
 if(action==='shop-item'){openStoreItem(button.dataset.id);return true;}
 if(action==='purchase'){const result=purchaseCosmetic(state,button.dataset.id);if(!result.ok){toast(result.reason==='funds'?'You need more virtual credits.':result.reason==='owned'?'You already own this item.':'That item is unavailable.');return true;}save();drawScene();openStoreItem(result.item.id);toast(`${result.item.name} is yours. Equipped and saved.`);return true;}
 if(action==='store-equip'){const item=STORE_ITEMS.find(c=>c.id===button.dataset.id);if(item&&isUnlocked(item,state)){state[item.category]=item.id;save();drawScene();toast('Outfit updated.');}return true;}
 if(action==='chat-target'){chatTarget=button.dataset.index==='room'?null:Number(button.dataset.index);if(chatTarget!==null)hotel.engage(chatTarget);openChat();return true;}
 if(action==='resident-topic'){chatTarget=Number(button.dataset.index);const g=GUESTS[chatTarget],topic=Number(button.dataset.topic);if(g?.topics[topic])sendChat(g.topics[topic].label,topic);return true;}
 return false;
}

function styleChanged(){state.decorated++;updateProgress();drawScene();openStyle();}
document.addEventListener('input',e=>{if(e.target.id==='name-input'){state.name=e.target.value.trim().slice(0,18)||'Alex';save();drawScene();}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();sendChat($('#chat-input').value);}});
panel.addEventListener('cancel',e=>{if(spinning)e.preventDefault();else{panelType='';navActive(currentRoom==='suite'?'suite':'hotel');}});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('.wordmark').addEventListener('click',e=>{e.preventDefault();enterRoom('suite');});
setupNav();applyControls();updateHud();updateSidebar();enterRoom('suite');requestAnimationFrame(loop);
